function validate(s){if(!s||s.version!==1||!Number.isSafeInteger(s.diamonds)||s.diamonds<0||!Number.isInteger(s.pity)||s.pity<0||s.pity>49||!Number.isSafeInteger(s.points)||s.points<0||!s.owned||typeof s.owned!=='object'||Array.isArray(s.owned)||!Array.isArray(s.rewards)||new Set(s.rewards).size!==s.rewards.length||s.rewards.some(x=>!['stage10','stage20','chapter1'].includes(x))||!Array.isArray(s.last)||s.last.length>10)throw Error('召喚存檔無效，未覆寫資料');for(const [id,n]of Object.entries(s.owned))if(!pool.some(h=>h.id===id)||!Number.isSafeInteger(n)||n<1)throw Error('角色資料無效');for(const r of s.last)if(!pool.some(h=>h.id===r.id)||typeof r.isNew!=='boolean')throw Error('召喚結果無效');if(s.onboarding!==undefined&&(!s.onboarding||['intro','first','complete'].some(k=>typeof s.onboarding[k]!=='boolean')||s.onboarding.first&&!s.onboarding.intro||s.onboarding.complete&&!s.onboarding.first))throw Error('教學資料無效');return JSON.parse(JSON.stringify(s))}
